WITH valid AS (SELECT *, SUBSTRING(location, 1, 2) location_prefix FROM departments WHERE location NOT IN ('Singapore', 'London')), with_windows AS (SELECT id, dept_name, location, location_prefix, NTILE(10) OVER (ORDER BY budget DESC, id) budget_bucket, LAG(budget, 1) OVER (PARTITION BY dept_name ORDER BY budget, id) prev_budget FROM valid), deduped AS (SELECT id, location, prev_budget FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name, location ORDER BY prev_budget DESC, id) AS latest_rank FROM with_windows) x WHERE latest_rank = 1), remaining_keys AS (SELECT id, location FROM deduped EXCEPT ALL SELECT id, location FROM departments WHERE dept_name IN ('HR', 'Sales')), kept_rows AS (SELECT s.* FROM deduped s INNER JOIN remaining_keys k ON s.id = k.id AND s.location = k.location), base AS (SELECT *, COALESCE(location, 'Unknown') location_filled, COALESCE(location, 'NONE') location_clean FROM kept_rows WHERE location IS NOT NULL), valid_departments AS (SELECT id, location, location_filled, location_clean, INITCAP(TRIM(location)) location_title FROM base WHERE location = 'Tokyo') SELECT location, COUNT(DISTINCT id) AS distinct_ids, COUNT_IF(location = 'London') AS london_events, SORT_ARRAY(COLLECT_SET(location)) AS location_list FROM valid_departments GROUP BY location;
